// Site search (gh:#909, #906 spec §2.1): for a reader who already knows
// roughly what they want. Results are grouped Science / Code / Demo.
//
// The index is search.json at the site root, generated by
// scripts/build-search-index.sh from the books and pathway pages the site
// builds; the crates come from code-map/code_map.json, generated by
// kovan-cli. Nothing here is a hand-kept list.
//
// Full text (gh:#876 item 8): search-text.json, written by
// `kovan-cli site-index` (crates/kovan/src/site_search.rs) from every built
// page, holds each page and an inverted index (term -> [page, weight],
// terms sorted). A query's words are tokenised exactly as the index's were
// (the block between the tokenise markers; docs/site/check-search.js runs it
// against search-tokenise-fixture.json, as the Rust tests do), and each must
// match some term as a prefix; pages are ranked by their summed weight and
// merged with the entries above by URL.
//
// Markup: <form class="site-search" data-scope="all|science|code|demo">
//           <input type="search" ...> <button>Search</button></form>
//         <div class="search-results" aria-live="polite"></div>   (right after the form)
// The script must be loaded with a src, so it can find the site root.
(function () {
  "use strict";
  var me = document.currentScript;
  if (!me) return;
  var root = new URL(".", me.src);
  var GROUPS = [["science", "Science"], ["code", "Code"], ["demo", "Demo"]];
  var SHOWN = 6;
  var index = null, loading = null, full = { docs: [], terms: [] };

  // tokenise-begin (kept identical to kovan::site_search::tokenise)
  function tokenise(s) {
    return String(s).toLowerCase().split(/[^\p{Alphabetic}\p{N}]+/u).filter(function (t) {
      return Array.from(t).length >= 2 || /\p{N}/u.test(t);
    });
  }
  // tokenise-end

  // Pages whose terms match every word as a prefix: {page: summed weight}.
  function fullText(words) {
    var terms = full.terms, total = null;
    for (var i = 0; i < words.length; i++) {
      var w = words[i], lo = 0, hi = terms.length, mine = {};
      while (lo < hi) { var mid = (lo + hi) >> 1; if (terms[mid][0] < w) lo = mid + 1; else hi = mid; }
      for (var j = lo; j < terms.length && terms[j][0].lastIndexOf(w, 0) === 0; j++) {
        terms[j][1].forEach(function (p) { mine[p[0]] = (mine[p[0]] || 0) + p[1]; });
      }
      if (total === null) total = mine;
      else { var next = {}; for (var d in total) if (mine[d]) next[d] = total[d] + mine[d]; total = next; }
    }
    return total || {};
  }

  function load() {
    if (loading) return loading;
    var get = function (path) {
      return fetch(new URL(path, root)).then(function (r) {
        if (!r.ok) throw new Error(path + ": " + r.status);
        return r.json();
      });
    };
    loading = Promise.all([
      get("search.json"),
      get("code-map/code_map.json").catch(function () { return { crates: [] }; }),
      get("search-text.json").catch(function () { return { docs: [], terms: [] }; })
    ]).then(function (res) {
      full = res[2];
      var all = res[0].slice();
      (res[1].crates || []).forEach(function (c) {
        all.push({ k: "code", t: "Crate " + c.name + (c.backronym ? " (" + c.backronym + ")" : ""),
          u: "code-map/#" + encodeURIComponent(c.name), x: (c.description || "") + " " + (c.topic || "") });
      });
      all.forEach(function (e) { e.tl = e.t.toLowerCase(); e.xl = (e.x || "").toLowerCase() + " " + e.u.toLowerCase(); });
      index = all;
      return all;
    });
    return loading;
  }

  // Every word of the query must appear; title hits count most, then a hit
  // at the start of a word.
  function score(e, words) {
    var s = 0;
    for (var i = 0; i < words.length; i++) {
      var w = words[i], t = e.tl.indexOf(w), x = e.xl.indexOf(w);
      if (t < 0 && x < 0) return 0;
      if (t >= 0) s += (t === 0 || /[^a-z0-9]/.test(e.tl.charAt(t - 1))) ? 6 : 4;
      if (x >= 0) s += 1;
    }
    return s;
  }
  function norm(q) {
    return q.toLowerCase().replace(/[(),]/g, " ").split(/\s+/).filter(function (w) { return w.length > 0; });
  }
  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; });
  }

  function render(out, q, scope) {
    var words = norm(q);
    if (!words.length) { out.innerHTML = ""; return; }
    var hits = index.map(function (e) { return { e: e, s: 3 * score(e, words) }; })
      .filter(function (h) { return h.s > 0; });
    // Full text: a page already listed gains its weight; any other joins.
    var byUrl = {};
    hits.forEach(function (h) { byUrl[h.e.u] = h; });
    var ft = fullText(tokenise(q));
    for (var d in ft) {
      var doc = full.docs[d], h0 = byUrl[doc.u];
      if (h0) { h0.s += ft[d]; if (!h0.e.p) h0.e.p = doc.p; }
      else hits.push(byUrl[doc.u] = { e: { k: doc.k, t: doc.t || doc.u, u: doc.u, p: doc.p }, s: ft[d] });
    }
    hits = hits.filter(function (h) { return scope === "all" || h.e.k === scope; })
      .sort(function (a, b) { return b.s - a.s || a.e.t.length - b.e.t.length; });
    if (!hits.length) {
      out.innerHTML = "<p class='search-none'>Nothing found for <b>" + esc(q) + "</b>. Try fewer or shorter words.</p>";
      return;
    }
    var h = "";
    GROUPS.forEach(function (g) {
      var list = hits.filter(function (x) { return x.e.k === g[0]; });
      if (!list.length) return;
      h += "<section class='search-group'><h3>" + g[1] + " <span class='n'>" + list.length + "</span></h3><ul>";
      list.forEach(function (x, i) {
        var pre = x.e.p ? "<br><small class='search-preview'>" + esc(x.e.p.length > 140 ? x.e.p.slice(0, 140) + "…" : x.e.p) + "</small>" : "";
        h += "<li" + (i >= SHOWN ? " hidden" : "") + "><a href='" + esc(new URL(x.e.u, root).href) + "'>" + esc(x.e.t) + "</a>" + pre + "</li>";
      });
      h += "</ul>";
      if (list.length > SHOWN) h += "<button type='button' class='search-more'>Show all " + list.length + "</button>";
      h += "</section>";
    });
    out.innerHTML = h;
  }

  function wire(form) {
    var input = form.querySelector("input");
    var out = form.nextElementSibling;
    var scope = form.getAttribute("data-scope") || "all";
    if (!input || !out) return;
    var run = function () {
      var q = input.value;
      load().then(function () { render(out, q, scope); })
        .catch(function (err) { out.innerHTML = "<p class='search-none'>Search is unavailable: " + esc(err.message) + "</p>"; });
    };
    var timer = null;
    input.addEventListener("input", function () { clearTimeout(timer); timer = setTimeout(run, 150); });
    form.addEventListener("submit", function (ev) { ev.preventDefault(); run(); });
    out.addEventListener("click", function (ev) {
      var b = ev.target.closest ? ev.target.closest(".search-more") : null;
      if (!b) return;
      var items = b.parentNode.querySelectorAll("li[hidden]");
      for (var i = 0; i < items.length; i++) items[i].hidden = false;
      b.remove();
    });
    // A link can carry the query: index.html?q=delta+tracking.
    var q = new URLSearchParams(location.search).get("q");
    if (q) { input.value = q; run(); }
  }

  function start() {
    var forms = document.querySelectorAll("form.site-search");
    for (var i = 0; i < forms.length; i++) wire(forms[i]);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start);
  else start();
})();
